mapper.select:
SELECT * FROM ( SELECT a.*, ROW_NUMBER() OVER (ORDER BY TO_DATE(a.schdul_date, 'YYYY-MM-DD') DESC, a.attend ASC NULLS FIRST) AS rnum FROM ( SELECT s.schdul_no, TO_CHAR(s.schdul_date, 'YYYY-MM-DD') as schdul_date, s.user_no, s.attend, s.leave, s.working_time, s.status, u.user_nm, st.store_nm, p.position_nm FROM schedule s JOIN tb_user u ON s.user_no = u.user_no JOIN store_employee se ON u.user_no = se.user_no JOIN store st ON se.store_no = st.store_no LEFT JOIN position p ON se.position_no = p.position_no WHERE st.store_no = #{storeNo} AND st.store_status = 'Y'
AND TO_CHAR(s.schdul_date, 'YYYY-MM') = #{searchDate}
AND COALESCE(s.status, '미정') = #{status}
) a ) b WHERE rnum BETWEEN (#{page} - 1) * #{size} + 1 AND #{page} * #{size}

SELECT COUNT(*)
FROM schedule s
JOIN tb_user u ON s.user_no = u.user_no
JOIN store_employee se ON u.user_no = se.user_no
JOIN store st ON se.store_no = st.store_no
WHERE st.store_no = #{storeNo}

    AND TO_CHAR(s.schdul_date, 'YYYY-MM') = #{searchDate}


    AND COALESCE(s.status, '미정') = #{status}
